// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address initialDao, address newDao, address caller) public {
        // Admissible domain: caller must not accidentally be initialDao or DAO address at first.
        vm.assume(initialDao != address(0));
        vm.assume(newDao != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != initialDao);
        vm.assume(newDao != c.DAO());

        // 1. Set up initial DAO via setDAO from a third-party while unconfigured.
        //    (Reference allows this because !configured is true; DAO becomes initialDao.)
        vm.prank(address(0xBEEF));
        c.setDAO(initialDao);
        assertEq(c.DAO(), initialDao);

        // 2. Configure the contract so setDAO enters the configured branch of the reference.
        c.endConfiguration();
        assertTrue(c.configured());

        // 3. Now attempt setDAO from a caller that is NOT the current DAO.
        //    Reference: require(DAO == msg.sender || !configured) => reverts (DAO unchanged).
        //    Mutant: require(!configured) => still false... wait, configured is true, so it reverts too.
        //    Need a case where mutant differs: mutant only checks !configured. To bypass the reference's
        //    DAO check while mutant succeeds, configured must be false. But then reference would also allow.
        //
        //    The actual divergence: reference allows when msg.sender == DAO OR !configured;
        //    mutant allows only when !configured. When configured == true and caller != DAO,
        //    BOTH revert. When configured == false, both allow. When configured == true and
        //    caller == DAO, reference allows but mutant REVERTS.
        //
        //    So the rule that separates them: after configuration, the current DAO can still
        //    update DAO in the reference, but the mutant forbids it because it only checks !configured.
        //
        // 3. Call setDAO as the current DAO; reference should succeed, mutant should revert.
        bool ok;
        vm.prank(initialDao);
        try c.setDAO(newDao) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok == true, DAO == newDao.
        // Mutant: ok == false (revert), DAO unchanged == initialDao.
        // General rule: when configured and caller == current DAO, setDAO must succeed and update DAO.
        assertTrue(ok && c.DAO() == newDao);
    }
}

